527	// 子命令选项解析：allowed 中列出的选项均需带值；multi 中的选项可重复
528	function parseFlags(args: string[], allowed: string[], multi: string[] = []): ParsedFlags {
529	  const allowedSet = new Set(allowed);
530	  const multiSet = new Set(multi);
531	  const values = new Map<string, string[]>();
532	  const positionals: string[] = [];
533	
534	  const takeValue = (key: string, inline: string | undefined, index: number): [string, number] => {
535	    if (inline !== undefined) return [inline, index];
536	    const v = args[index + 1];
537	    if (v === undefined || v.startsWith('-')) {
538	      throw new UsageError(`选项 --${key} 缺少值`);
539	    }
540	    return [v, index + 1];
541	  };
542	
543	  for (let i = 0; i < args.length; i++) {
544	    const a = args[i];
545	    if (a.startsWith('--')) {
546	      let key: string;
547	      let inline: string | undefined;
548	      const eq = a.indexOf('=');
549	      if (eq >= 0) {
550	        key = a.slice(2, eq);
551	        inline = a.slice(eq + 1);
552	      } else {
553	        key = a.slice(2);
554	      }
555	      if (!allowedSet.has(key)) throw new UsageError(`未知选项: --${key}`);
556	      let v: string;
557	      [v, i] = takeValue(key, inline, i);
558	      if (v === '') throw new UsageError(`选项 --${key} 的值不能为空`);
559	      if (!multiSet.has(key) && values.has(key)) {
560	        throw new UsageError(`选项 --${key} 只能指定一次`);
561	      }
562	      const list = values.get(key) ?? [];
563	      list.push(v);
564	      values.set(key, list);
565	    } else if (a.startsWith('-') && a !== '-') {
566	      throw new UsageError(`未知参数: ${a}`);
567	    } else {
568	      positionals.push(a);
569	    }
570	  }
571	  return {values, positionals};
572	}
573	
574	function requireFlag(values: Map<string, string[]>, key: string): string {
575	  const v = values.get(key)?.[0];
576	  if (v === undefined) throw new UsageError(`缺少必需选项 --${key}`);
577	  return v;
578	}
