668	async function cmdRescheduleBooking(args: string[]): Promise<void> {
669	  const {values, positionals} = parseFlags(args, ['start', 'end', 'resource'], ['resource']);
670	  if (positionals.length !== 1) {
671	    throw new UsageError('用法: reschedule-booking <预约标识> [--start ...] [--end ...] [--resource ...]');
672	  }
673	  const id = positionals[0];
674	
675	  const file = activeDataFile;
676	  const store = await loadStore(file);
677	  const booking = store.bookings.find((b) => b.id === id);
678	  if (!booking) throw new BizError(`未知预约标识: ${id}`);
679	  if (booking.status === 'cancelled') {
680	    throw new BizError(`预约 ${id} 已取消，不能改期`);
681	  }
682	
683	  const hasTime = values.has('start') || values.has('end');
684	  const hasResource = values.has('resource');
685	  if (!hasTime && !hasResource) {
686	    throw new BizError('未指定任何改动：请提供 --start/--end 修改时间，或 --resource 替换资源（可同时提供）');
687	  }
688	
689	  const startRaw = values.get('start')?.[0] ?? booking.start;
690	  const endRaw = values.get('end')?.[0] ?? booking.end;
691	  const startMin = parseDateTime(startRaw, '预约开始时间');
692	  const endMin = parseDateTime(endRaw, '预约结束时间');
693	  if (endMin <= startMin) {
694	    throw new BizError(`预约结束时间必须晚于开始时间（开始: ${startRaw}，结束: ${endRaw}），允许跨日`);
695	  }
696	
697	  let ids: string[] = booking.resourceIds;
698	  if (hasResource) {
699	    const resourceArgs = values.get('resource')!;
700	    ids = resolveResourceIds(store, resourceArgs);
701	  }
702	
703	  assertOpenCoverage(store, ids, startMin, endMin);
704	  // 改期检查排除自身
705	  assertNoConflicts(findConflicts(store, ids, startMin, endMin, id), store);
706	
707	  // 全部可用后整体替换旧安排并落盘；失败则本进程内存与磁盘上的原安排都不变。
708	  // seriesId 不随改期变化：改期后仍属原系列。
709	  booking.start = startRaw;
710	  booking.end = endRaw;
711	  booking.resourceIds = ids;
712	  await saveStore(file, store);
713	  console.log(`已改期预约 ${id}（标识保持不变）`);
714	  if (booking.seriesId) console.log(`  所属系列: ${booking.seriesId}（改期后仍属该系列）`);
715	  console.log(`  时间: ${startRaw} → ${endRaw}`);
716	  console.log(`  资源: ${formatResourceIds(store, ids)}`);
717	}
